// Shared browser/Node validation for the rectangular contour Studio operation.
// Toolpaths remain generated by the Rust kernel, never by this model.
(function(root){
'use strict';
const facing=root.FertigungsstudioFacingModel||
 (typeof require==='function'?require('./studio-facing-model.cjs'):null);
function number(v,name){
 if(v===null||v===undefined||v==='')throw Error(name+' fehlt.');
 const n=Number(v);
 if(!Number.isFinite(n))throw Error(name+' ist keine gültige Zahl.');
 return n;
}
function positive(v,name){
 const n=number(v,name);
 if(n<=0||n>1_000_000)throw Error(name+' muss größer 0 und höchstens 1.000.000 sein.');
 return n;
}
function eligible(tool){
 return facing.eligible(tool)&&tool.type==='Schaftfräser';
}
function prepare(project,tool,form){
 if(!project?.stock)throw Error('Rohteil im Setup fehlt.');
 if(!eligible(tool))throw Error('Ein Schaftfräser mit gültiger Geometrie wird benötigt.');
 const stock=project.stock, width=positive(stock.x,'Rohteil X'),
 length=positive(stock.y,'Rohteil Y'), height=positive(stock.z,'Rohteil Z');
 const diameter=positive(tool.diameter,'Werkzeugdurchmesser'),
 cuttingLength=positive(tool.cutLength,'Schneidenlänge');
 const id=number(tool.id,'Werkzeugnummer');
 if(!Number.isInteger(id)||id<1||id>9999)throw Error('Ungültige Werkzeugnummer.');
 const depth=positive(form.depth,'Abtragstiefe'),stepdown=positive(form.stepdown,'Tiefenzustellung');
 const clearance=positive(form.clearance,'Sicherheitshöhe'),
 cuttingFeed=positive(form.cuttingFeed,'Schnittvorschub'),
 plungeFeed=positive(form.plungeFeed,'Eintauchvorschub');
 if(depth>height||depth>cuttingLength)throw Error('Abtragstiefe überschreitet Rohteil oder Schneidenlänge.');
 if(height+clearance>1_000_000)throw Error('Sicherheitshöhe liegt außerhalb des zulässigen Bereichs.');
 const side=form.side??'outside',direction=form.direction??'climb',spindle=form.spindle??'M3';
 if(!['inside','outside'].includes(side))throw Error('Ungültige Konturseite.');
 if(!['climb','conventional'].includes(direction))throw Error('Ungültige Fräsrichtung.');
 if(!['M3','M4'].includes(spindle))throw Error('Ungültige Spindelrichtung.');
 if(form.source==='model'){
  const points=form.points;
  if(!Array.isArray(points)||points.length<3||points.length>2048)
   throw Error('Bitte eine geschlossene STL-Kontur im 3D-Modell auswählen.');
  const vertices=points.map(p=>{
   if(!Array.isArray(p)||p.length!==2)throw Error('Ungültige Modellkontur.');
   return p.map((v,i)=>{
    const n=number(v,'Konturkoordinate');
    if(n<0||n>(i===0?width:length))throw Error('Modellkontur liegt außerhalb des Rohteils.');
    return n;
   });
  });
  const depthPasses=Math.ceil(depth/stepdown);
  if(!Number.isFinite(depthPasses)||depthPasses*(vertices.length+3)>100000)
   throw Error('Zu viele Werkzeugbewegungen.');
  const clockwise=(spindle==='M3')===(side==='inside')
    ?direction==='climb':direction!=='climb';
  return {
   numbers:[width,length,height,depth,diameter,stepdown,id,cuttingLength,
    cuttingFeed,plungeFeed,clearance,side==='inside'?1:0,clockwise?1:0,
    vertices.length,...vertices.flat()],
   source:'model',depthPasses,estimatedMoves:depthPasses*(vertices.length+3),
   start:null,
   settings:{toolId:id,depth,stepdown,clearance,cuttingFeed,plungeFeed,
    source:'model',side,direction,spindle,clockwise,vertexCount:vertices.length}
  };
 }
 const marginX=number(form.marginX??0,'Randabstand X'),
 marginY=number(form.marginY??0,'Randabstand Y');
 if(marginX<0||marginY<0||marginX>1_000_000||marginY>1_000_000)
   throw Error('Randabstände dürfen nicht negativ sein.');
 if(side==='outside'&&(marginX!==0||marginY!==0))
   throw Error('Außenkontur liegt auf dem Rohteilrand; Randabstände sind hier 0.');
 if(side==='inside'&&(marginX<=0||marginY<=0||width-2*marginX<=diameter||length-2*marginY<=diameter))
   throw Error('Innenkontur liegt nicht vollständig mit Werkzeugdurchmesser im Rohteil.');
 const minX=marginX,minY=marginY,maxX=width-marginX,maxY=length-marginY;
 const r=diameter/2, x0=side==='outside'?minX-r:minX+r,
 x1=side==='outside'?maxX+r:maxX-r,
 y0=side==='outside'?minY-r:minY+r,
 y1=side==='outside'?maxY+r:maxY-r;
 if(![x0,x1,y0,y1].every(v=>Number.isFinite(v)&&Math.abs(v)<=1_000_000))
   throw Error('Konturkoordinaten außerhalb des Bereichs.');
 const depthPasses=Math.ceil(depth/stepdown);
 if(!Number.isFinite(depthPasses)||depthPasses*7>100_000)
   throw Error('Zu viele Werkzeugbewegungen.');
 // M3 seen clockwise from above. At the exterior -Y edge the tool tangential
 // contact moves toward +X; the inner contact uses the opposite tool side.
 // This classification applies to the selected boundary contact only.
 const clockwise=(spindle==='M3')===(side==='inside') ?
   direction==='climb' : direction!=='climb';
 return {
  numbers:[width,length,height,depth,diameter,stepdown,diameter/2,id,cuttingLength,
   cuttingFeed,plungeFeed,clearance,side==='inside'?1:0,clockwise?1:0,marginX,marginY],
  depthPasses,estimatedMoves:depthPasses*7,
  start:{x:x0,y:y0,z:height+clearance},
  toolBounds:{minX:x0,minY:y0,maxX:x1,maxY:y1},
  settings:{toolId:id,depth,stepdown,clearance,cuttingFeed,plungeFeed,
   side,direction,spindle,marginX,marginY,clockwise}
 };
}
const api={eligible,prepare,recommendedFeed:facing.recommendedFeed};
root.FertigungsstudioContourModel=api;
if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(globalThis);
